import{c as a,Q as h,j as o,m as e}from"./chunks/framework.DOi4mjdC.js";const s=JSON.parse('{"title":"西游记","description":"","frontmatter":{"id":"xiyouji","title":"西游记","author":"吴承恩","dynasty":"明代","cover":"/covers/xiyouji.jpg","sort":4,"literaryValue":"《西游记》是中国古典四大名著之一，讲述了唐僧师徒四人西天取经，历经九九八十一难的故事，是中国古代神魔小说的经典之作。"},"headers":[],"relativePath":"books/mingzhu/xiyouji.md","filePath":"books/mingzhu/xiyouji.md"}'),r={name:"books/mingzhu/xiyouji.md"};function c(u,i,x,f,t,y){return h(),o("div",null,[...i[0]||(i[0]=[e('<h1 id="西游记" tabindex="-1">西游记 <a class="header-anchor" href="#西游记" aria-label="Permalink to &quot;西游记&quot;">​</a></h1><h2 id="作品简介" tabindex="-1">作品简介 <a class="header-anchor" href="#作品简介" aria-label="Permalink to &quot;作品简介&quot;">​</a></h2><p>《西游记》是中国古代第一部浪漫主义章回体长篇神魔小说。现存明刊百回本《西游记》均无作者署名。清代学者吴玉搢等首先提出《西游记》作者是明代吴承恩。</p><p>全书主要描写了孙悟空出世及大闹天宫後，遇见了唐僧、猪八戒、沙僧和白龙马，西行取经，一路上历经艰险、降妖除魔，经历了九九八十一难，终于到达西天见到如来佛祖，最终五圣成真的故事。该小说以&quot;唐僧取经&quot;这一历史事件为蓝本，通过作者的艺术加工，深刻地描绘了明代社会现实。</p><h2 id="作者介绍" tabindex="-1">作者介绍 <a class="header-anchor" href="#作者介绍" aria-label="Permalink to &quot;作者介绍&quot;">​</a></h2><p><strong>吴承恩</strong>（约1500年—1582年），字汝忠，号射阳山人，明代杰出的小说家。淮安府山阳县（今江苏省淮安市淮安区）人。</p><p>吴承恩自幼敏慧，博览群书，尤其喜爱神话故事。在科举中屡遭挫折，嘉靖中补贡生。嘉靖四十五年（1566年）任浙江长兴县丞。殊途由于宦途困顿，晚年绝意仕进，闭门著述。</p><h2 id="文学价值" tabindex="-1">文学价值 <a class="header-anchor" href="#文学价值" aria-label="Permalink to &quot;文学价值&quot;">​</a></h2><p>《西游记》是中国神魔小说的经典之作，达到了古代长篇浪漫主义小说的巅峰，与《三国演义》《水浒传》《红楼梦》并称为中国古典四大名著。《西游记》自问世以来在民间广为流传，各式各样的版本层出不穷，明代刊本有六种，清代刊本、抄本也有七种，典籍所记已佚版本十三种。</p><h2 id="经典人物" tabindex="-1">经典人物 <a class="header-anchor" href="#经典人物" aria-label="Permalink to &quot;经典人物&quot;">​</a></h2><ul><li><p><strong>孙悟空</strong>：又名孙行者、齐天大圣。由东胜神洲傲来国花果山上的一块仙石孕育而生，拜师菩提祖师学得七十二变、筋斗云等神通。大闹天宫后被如来佛祖压在五行山下五百年，经观音菩萨点化，保护唐僧西天取经。他机智勇敢、嫉恶如仇，是取经团队的核心战力。</p></li><li><p><strong>唐僧</strong>：俗姓陈，小名江流儿，法名玄奘。如来佛祖二弟子金蝉子转世，奉唐太宗之命前往西天取经。他心地善良、意志坚定，但有时迂腐固执、不辨善恶，多次错怪孙悟空。</p></li><li><p><strong>猪八戒</strong>：法号悟能，原是天庭的天蓬元帅，因调戏嫦娥被贬下凡，错投猪胎。他性格憨厚、好吃懒做、贪恋女色，但关键时刻也能挺身而出，是取经路上的重要帮手。</p></li><li><p><strong>沙僧</strong>：法号悟净，原是天庭的卷帘大将，因打碎琉璃盏被贬流沙河。他忠厚老实、任劳任怨，负责挑担，是取经团队中最踏实稳重的成员。</p></li></ul><hr><h2 id="章节目录" tabindex="-1">章节目录 <a class="header-anchor" href="#章节目录" aria-label="Permalink to &quot;章节目录&quot;">​</a></h2><div class="toc-section"><div class="toc-section-title">第一卷 · 猴王出世（第1回 - 第20回）</div><div class="toc-grid"><p><a href="./xiyouji/ch1">第一回 灵根育孕源流出　心性修持大道生</a><a href="./xiyouji/ch2">第二回 悟彻菩提真妙理 断魔归本合元神</a><a href="./xiyouji/ch3">第三回 四海千山皆拱伏 九幽十类尽除名</a><a href="./xiyouji/ch4">第四回 官封弼马心何足 名注齐天意未宁</a><a href="./xiyouji/ch5">第五回 乱蟠桃大圣偷丹 反天宫诸神捉怪</a><a href="./xiyouji/ch6">第六回 观音赴会问原因 小圣施威降大圣</a><a href="./xiyouji/ch7">第七回 八卦炉中逃大圣 五行山下定心猿</a><a href="./xiyouji/ch8">第八回 我佛造经传极乐 观音奉旨上长安</a><a href="./xiyouji/ch9">第九回 袁守诚妙算无私曲 老龙王拙计犯天条</a><a href="./xiyouji/ch10">第十回 二将军宫门镇鬼 唐太宗地府还魂</a><a href="./xiyouji/ch11">第十一回 还受生唐王遵善果 度孤魂萧瑀正空门</a><a href="./xiyouji/ch12">第十二回 玄奘秉诚建大会 观音显象化金蝉</a><a href="./xiyouji/ch13">第十三回 陷虎穴金星解厄 双叉岭伯钦留僧</a><a href="./xiyouji/ch14">第十四回 心猿归正 六贼无踪</a><a href="./xiyouji/ch15">第十五回 蛇盘山诸神暗佑 鹰愁涧意马收缰</a><a href="./xiyouji/ch16">第十六回 观音院僧谋宝贝 黑风山怪窃袈裟</a><a href="./xiyouji/ch17">第十七回 孙行者大闹黑风山 观世音收伏熊罴怪</a><a href="./xiyouji/ch18">第十八回 观音院唐僧脱难 高老庄行者降魔</a><a href="./xiyouji/ch19">第十九回 云栈洞悟空收八戒 浮屠山玄奘受心经</a><a href="./xiyouji/ch20">第二十回 黄风岭唐僧有难 半山中八戒争先</a></p></div></div><div class="toc-section"><div class="toc-section-title">第二卷 · 取经缘起（第21回 - 第40回）</div><div class="toc-grid"><p><a href="./xiyouji/ch21">第二十一回 护法设庄留大圣 须弥灵吉定风魔</a><a href="./xiyouji/ch22">第二十二回 八戒大战流沙河 木叉奉法收悟净</a><a href="./xiyouji/ch23">第二十三回 三藏不忘本 四圣试禅心</a><a href="./xiyouji/ch24">第二十四回 万寿山大仙留故友 五庄观行者窃人参</a><a href="./xiyouji/ch25">第二十五回 镇元仙赶捉取经僧 孙行者大闹五庄观</a><a href="./xiyouji/ch26">第二十六回 孙悟空三岛求方 观世音甘泉活树</a><a href="./xiyouji/ch27">第二十七回 尸魔三戏唐三藏 圣僧恨逐美猴王</a><a href="./xiyouji/ch28">第二十八回 花果山群妖聚义 黑松林三藏逢魔</a><a href="./xiyouji/ch29">第二十九回 脱难江流来国土 承恩八戒转山林</a><a href="./xiyouji/ch30">第三十回 邪魔侵正法 意马忆心猿</a><a href="./xiyouji/ch31">第三十一回 猪八戒义激猴王 孙行者智降妖怪</a><a href="./xiyouji/ch32">第三十二回 平顶山功曹传信 莲花洞木母逢灾</a><a href="./xiyouji/ch33">第三十三回 外道迷真性 元神助本心</a><a href="./xiyouji/ch34">第三十四回 魔王巧算困心猿 大圣腾那骗宝贝</a><a href="./xiyouji/ch35">第三十五回 外道施威欺正性 心猿获宝伏邪魔</a><a href="./xiyouji/ch36">第三十六回 心猿正处诸缘伏 劈破旁门见月明</a><a href="./xiyouji/ch37">第三十七回 鬼王夜谒唐三藏 悟空神化引婴儿</a><a href="./xiyouji/ch38">第三十八回 婴儿问母知邪正 金木参玄见假真</a><a href="./xiyouji/ch39">第三十九回 一粒金丹天上得 三年故主世间生</a><a href="./xiyouji/ch40">第四十回 婴儿戏化禅心乱 猿马刀归木母空</a></p></div></div><div class="toc-section"><div class="toc-section-title">第三卷 · 降妖伏魔（第41回 - 第60回）</div><div class="toc-grid"><p><a href="./xiyouji/ch41">第四十一回 心猿遭火败 木母被魔擒</a><a href="./xiyouji/ch42">第四十二回 大圣殷勤拜南海 观音慈善缚红孩</a><a href="./xiyouji/ch43">第四十三回 黑河妖孽擒僧去 西洋龙子捉鼍回</a><a href="./xiyouji/ch44">第四十四回 法身元运逢车力 心正妖邪度脊关</a><a href="./xiyouji/ch45">第四十五回 三清观大圣留名 车迟国猴王显法</a><a href="./xiyouji/ch46">第四十六回 外道弄强欺正法 心猿显圣灭诸邪</a><a href="./xiyouji/ch47">第四十七回 圣僧夜阻通天水 金木垂慈救小童</a><a href="./xiyouji/ch48">第四十八回 魔弄寒风飘大雪 僧思拜佛履层冰</a><a href="./xiyouji/ch49">第四十九回 三藏有灾沉水宅 观音救难现鱼篮</a><a href="./xiyouji/ch50">第五十回 情乱性从因爱欲 神昏心动遇魔头</a><a href="./xiyouji/ch51">第五十一回 心猿空用千般计 水火无功难炼魔</a><a href="./xiyouji/ch52">第五十二回 悟空大闹金山兜洞 如来暗示主人公</a><a href="./xiyouji/ch53">第五十三回 禅主吞餐怀鬼孕 黄婆运水解邪胎</a><a href="./xiyouji/ch54">第五十四回 法性西来逢女国 心猿定计脱烟花</a><a href="./xiyouji/ch55">第五十五回 色邪淫戏唐三藏 性正修持不坏身</a><a href="./xiyouji/ch56">第五十六回 神狂诛草寇 道昧放心猿</a><a href="./xiyouji/ch57">第五十七回 真行者落伽山诉苦 假猴王水帘洞誊文</a><a href="./xiyouji/ch58">第五十八回 二心搅乱大乾坤 一体难修真寂灭</a><a href="./xiyouji/ch59">第五十九回 唐三藏路阻火焰山 孙行者一调芭蕉扇</a><a href="./xiyouji/ch60">第六十回 牛魔王罢战赴华筵 孙行者二调芭蕉扇</a></p></div></div><div class="toc-section"><div class="toc-section-title">第四卷 · 历劫西天（第61回 - 第80回）</div><div class="toc-grid"><p><a href="./xiyouji/ch61">第六十一回 猪八戒助力败魔王 孙行者三调芭蕉扇</a><a href="./xiyouji/ch62">第六十二回 涤垢洗心惟扫塔 缚魔归正乃修身</a><a href="./xiyouji/ch63">第六十三回 二僧荡怪闹龙宫 群圣除邪获宝贝</a><a href="./xiyouji/ch64">第六十四回 荆棘岭悟能努力 木仙庵三藏谈诗</a><a href="./xiyouji/ch65">第六十五回 妖邪假设小雷音 四众皆遭大厄难</a><a href="./xiyouji/ch66">第六十六回 诸神遭毒手 弥勒缚妖魔</a><a href="./xiyouji/ch67">第六十七回 拯救驼罗禅性稳 脱离秽污道心清</a><a href="./xiyouji/ch68">第六十八回 朱紫国唐僧论前 世孙行者施为三折肱</a><a href="./xiyouji/ch69">第六十九回 心主夜间修药物 君王筵上论妖邪</a><a href="./xiyouji/ch70">第七十回 妖魔宝放烟沙火 悟空计盗紫金铃</a><a href="./xiyouji/ch71">第七十一回 行者假名降怪犼 观音现象伏妖王</a><a href="./xiyouji/ch72">第七十二回 盘丝洞七情迷本 濯垢泉八戒忘形</a><a href="./xiyouji/ch73">第七十三回 情因旧恨生灾毒 心主遭魔幸破光</a><a href="./xiyouji/ch74">第七十四回 长庚传报魔头狠 行者施为变化能</a><a href="./xiyouji/ch75">第七十五回 心猿钻透阴阳窍 魔王还归大道真</a><a href="./xiyouji/ch76">第七十六回 心神居舍魔归性 木母同降怪体真</a><a href="./xiyouji/ch77">第七十七回 群魔欺本性 一体拜真如</a><a href="./xiyouji/ch78">第七十八回 比丘怜子遣阴神 金殿识魔谈道德</a><a href="./xiyouji/ch79">第七十九回 寻洞擒妖逢老寿 当朝正主救婴儿</a><a href="./xiyouji/ch80">第八十回 姹女育阳求配偶 心猿护主识妖邪</a></p></div></div><div class="toc-section"><div class="toc-section-title">第五卷 · 终成正果（第81回 - 第100回）</div><div class="toc-grid"><p><a href="./xiyouji/ch81">第八十一回 镇海寺心猿知怪 黑松林三众寻师</a><a href="./xiyouji/ch82">第八十二回 姹女求阳 元神护道</a><a href="./xiyouji/ch83">第八十三回 心猿识得丹头 姹女还归本性</a><a href="./xiyouji/ch84">第八十四回 难灭伽持圆大觉 法王成正体天然</a><a href="./xiyouji/ch85">第八十五回 心猿妒木母 魔主计吞禅</a><a href="./xiyouji/ch86">第八十六回 木母助威征怪物 金公施法灭妖邪</a><a href="./xiyouji/ch87">第八十七回 凤仙郡冒天止雨 孙大圣劝善施霖</a><a href="./xiyouji/ch88">第八十八回 禅到玉华施法会 心猿木母授门人</a><a href="./xiyouji/ch89">第八十九回 黄狮精虚设钉钯宴 金木土计闹豹头山</a><a href="./xiyouji/ch90">第九十回 师狮授受同归一 盗道缠禅静九灵</a><a href="./xiyouji/ch91">第九十一回 金平府元夜观灯 玄英洞唐僧供状</a><a href="./xiyouji/ch92">第九十二回 三僧大战青龙山 四星挟捉犀牛怪</a><a href="./xiyouji/ch93">第九十三回 给孤园问古谈因 天竺国朝王遇偶</a><a href="./xiyouji/ch94">第九十四回 四僧宴乐御花园 一怪空怀情欲喜</a><a href="./xiyouji/ch95">第九十五回 假合真形擒玉兔 真阴归正会灵元</a><a href="./xiyouji/ch96">第九十六回 寇员外喜待高僧 唐长老不贪富贵</a><a href="./xiyouji/ch97">第九十七回 金酬外护遭魔毒 圣显幽魂救本原</a><a href="./xiyouji/ch98">第九十八回 猿熟马驯方脱壳 功成行满见真如</a><a href="./xiyouji/ch99">第九十九回 九九数完魔灭尽 三三行满道归根</a><a href="./xiyouji/ch100">第一百回 径回东土 五圣成真</a></p></div></div><h2 id="作品评价" tabindex="-1">作品评价 <a class="header-anchor" href="#作品评价" aria-label="Permalink to &quot;作品评价&quot;">​</a></h2><p>《西游记》以诡异的想象、极度的夸张，突破时空，突破生死，突破神、人、物的界限，创造了一个光怪陆离、神异奇幻的境界。在这里，环境是天上地下、龙宫冥府、仙地佛境、险山恶水；形象多身奇貌异，似人似怪，神通广大，变幻莫测；故事则上天入地，翻江倒海，兴妖除怪，祭宝斗法。作者将这些奇人、奇事、奇境熔于一炉，构筑成了一个统一和谐的艺术整体，展现出一种奇幻美。这种奇幻美，看来&quot;极幻&quot;，却又令人感到&quot;极真&quot;。因为那些变幻莫测、惊心动魄的故事，或如现实的影子，或含生活的真理，表现得那么入情入理。那富丽堂皇、至高无上的天宫，就像人间朝廷在天上的造影；那等级森严、昏庸无能的仙卿，使人想起当朝的百官。扫荡横行霸道、凶残暴虐的妖魔，隐寓着铲除社会恶势力的愿望；歌颂升天入地、无拘无束的生活，也寄托着挣脱束缚、追求自由的精神。</p>',20)])])}const l=a(r,[["render",c]]);export{s as __pageData,l as default};
